"""Persist honest QA checkpoint, with no independent-review or approval claim."""
import json,hashlib,shutil,collections
from pathlib import Path
r=Path(__file__).resolve().parents[1]
def read(p):return json.loads((r/p).read_text())
def save(p,x):(r/p).write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
p=read('qa/Extraction_Progress.json');save('qa/Extraction_Progress.metadata_snapshot.json',p)
p['stage']='qa';p['full_study_complete']=False;p['notes']=['64 physical shells each have structure, DOCX, Locator Map and Metadata; 56 have no outstanding specifically identified fine-structure/source-conflict task, 8 remain. These categories are not approval states.','Fresh original PDF audit read all 86 pages and compared 4,124 physical blocks, 985 blanks and 73 physical footnotes by normalized character multiset. No differences; does not verify order, superscripts, scope or clinical interpretation.','Fresh actual XML audit checked 5,682 bookmarks; 300 documented corporate wrapper exclusions remain unlocated. Metadata schema/parity and hash audits rerun.','All 64 still pending independent visual/semantic and human approval. Current-turn image viewing failed (exec-server transport closed); earlier 77-page same-agent visual evidence retained, not promoted to independent QA.','No target replacement or optional replacement test performed. Pending checkpoint, not approved searchable library.'];save('qa/Extraction_Progress.json',p)
meta=read('Study_Metadata.json')['templates'];audit=read('qa/Actual_DOCX_Occurrence_Checks.json');src=read('qa/Fresh_Source_Character_Audit.json');foot=read('qa/Footnote_Cross_Layer_Checks.json');checks=[];loc=[];issues=[]
def check(tid,key,layer,status,details,paths):
 x=dict(check_id=(tid or 'GLOBAL')+'_'+key,template_id=tid,layer=layer,status=status,details=details,evidence_paths=paths);checks.append(x);return x
for t in meta:
 tid=t['identity']['template_id'];mp=f'intermediate/DOCX_Locator_Map/{tid}.json';st=f'intermediate/Structured_Shells/{tid}.json';remaining=tid in p['remaining_ids']
 check(tid,'CONTRACT','contract','pass','Actual metadata schema, IDs, physical note fields, structure/spec parity and provenance checked. Static only.',[st,mp,'Study_Metadata.json','qa/Metadata_Parity_Check.json'])
 check(tid,'SOURCE_CHARACTERS','contract','pass','Fresh original PDF normalized non-whitespace character multisets agree with every owned physical block and footnote; blank-cell regions contain no characters. Does not establish order, superscript or semantic correctness.',['qa/Fresh_Source_Character_Audit.json','qa/Footnote_Cross_Layer_Checks.json'])
 loc.append(check(tid,'DOCX_LOCATORS','docx','pass','Fresh actual DOCX XML: file hash, unique bookmark names/IDs, START/END order, containment, every located occurrence exact normalized text; persisted row/column/panel references resolve. Original source panel ownership still needs independent visual confirmation. 300 library-wide wrapper exclusions are explicitly unlocated.',['TFL_Template_Library/'+t['identity']['file_path'],mp,'qa/Actual_DOCX_Occurrence_Checks.json']))
 check(tid,'FOOTNOTES','contract','pass','Physical footnote count/ID/marker/text/order/typed scopes agree across persisted structure and Metadata; source character audit agrees; each physical note has a real visible-body bookmark. This does not approve the semantic rules.',['qa/Footnote_Cross_Layer_Checks.json','qa/Metadata_Parity_Check.json',mp])
 check(tid,'VISUAL_QA','visual','not_run','No fresh independent visual QA. Current image viewing unavailable: exec-server transport closed. Earlier same-agent 77-page render inspection retained; no promotion to semantic or independent correctness. DOCX hashes unchanged.',['qa/DOCX_Visual_Inspection.json','qa/DOCX_Visual_Page_Index.json','qa/DOCX_Render_Text_Audit.json'])
 check(tid,'SEMANTIC_INDEPENDENT','semantic','not_run','Independent clinical/semantic review has not run. Source display and unavailable SAP-body definitions remain distinct; source-supported interpretations are not approved target defaults.',['qa/Metadata_Issues.json','qa/Footnote_Semantic_Extraction.json'])
 uncertain=[f['footnote_id'] for f in t['footnotes'] if any(a['mapping_status'] in ['unresolved','inferred'] for a in f['applies_to_refs']) or any(a['mapping_status'] in ['unresolved','inferred'] for rule in f['semantic_rules'] for a in rule.get('applies_to_refs',[]))]
 if remaining or uncertain:
  check(tid,'SOURCE_INTERPRETATION','semantic','needs_review','Outstanding source/fine structure task: '+str(remaining)+'; physical/rule footnote scopes needing review: '+', '.join(uncertain)+'. Preserve original text and clinical conflicts; do not infer automatic application.',['qa/Metadata_Issues.json',st])
 check(tid,'HUMAN_APPROVAL','approval','not_run','No named reviewer/date/existing authorization record provided; quality stays pending.', ['Study_Metadata.json'])
# Carry actual source issues, not builder completion claims.
for path in ['source_registry/Mapping_Issues.json','qa/Extraction_Issues.json','qa/DOCX_Generation_Issues.json','qa/Metadata_Issues.json']:
 for x in read(path)['issues']:
  if x['severity']!='info' and x['status']!='resolved':
   y=dict(x);y['issue_id']='QA_'+str(len(issues)+1).zfill(4);y['description']=path+' ['+x['issue_id']+']: '+x['description'];issues.append(y)
issues.append(dict(issue_id='QA_REVIEW_UNAVAILABLE',template_id=None,severity='warning',category='independent_review',description='Independent visual/semantic and human approval not run for all 64. Current image-view attempt failed with exec-server transport closed; earlier same-agent evidence retained.',status='open',source_regions=[]))
inv=read('source_registry/Study_Source_Inventory.json');original=[]
for d in inv['sources']:
 h=hashlib.sha256((r/d['file_path']).read_bytes()).hexdigest();assert h==d['sha256'];assert h==hashlib.sha256((r.parent/Path(d['file_path']).name).read_bytes()).hexdigest();original.append(dict(document_id=d['document_id'],actual_sha256=h,status='pass'))
brief='04_TFL_Content_List_to_Shell_Generation_Agent copy 2.docx';assert (r/'original'/brief).read_bytes()==(r.parent/brief).read_bytes()
save('qa/Original_Integrity_Checks.json',dict(sources=original,project_brief_byte_identity='pass',physical_pdf_pages=src['pages_read'],source_character_differences=len(src['candidate_differences'])))
check(None,'ORIGINALS','contract','pass','Original source and project brief are byte-identical to supplied inputs. 86 actual PDF pages read, no fabricated absent-page scans.',['qa/Original_Integrity_Checks.json','source_registry/Source_Page_Index.json'])
report=dict(schema_version='2.4',study_id=p['study_id'],scope='Source-only v2.4 checkpoint. Fresh original-PDF character and actual-DOCX structural audit by the executing agent; NOT independent visual/clinical review. Native line order, superscripts, sparse cells, multi-panels, axes/units/methods/populations, typed footnote scope and clinical conflicts remain subject to independent source-image/semantic review. No target adaptation, simulation, retrieval pilot or approval.',counts=dict(physical_shells=len(p['manifest_ids']),structured_records=len(list((r/'intermediate/Structured_Shells').glob('*.json'))),docx_files=len(list((r/'TFL_Template_Library').rglob('*.docx'))),metadata_records=len(meta),approved_records=0,remaining_shells=len(p['remaining_ids'])+len(p['blocked_ids'])),checks=checks,issues=issues,human_approvals=[],full_study_complete=False)
save('qa/Study_QA_Report.json',report);save('qa/Source_Locator_Checks.json',dict(schema_version='2.4',checks=loc));save('qa/QA_Issues.json',dict(schema_version='2.4',stage='qa',issues=issues))
cor=read('qa/Corrections_Log.json');assert len(cor['corrections'])==2
save('qa/Review_Gaps.json',dict(specific_remaining_ids=p['remaining_ids'],blocked_ids=p['blocked_ids'],independent_visual_review_not_run_ids=p['manifest_ids'],independent_semantic_review_not_run_ids=p['manifest_ids'],human_approval_pending_ids=p['manifest_ids'],optional_replacement_test='not_run; optional, not a gate',current_qa_new_source_corrections=0,prior_source_supported_corrections_retained=len(cor['corrections'])))
shutil.copy2(r.parent/'TFL_Extraction_Full_Package_v2_4/prompts/05_QA_and_Package.txt',r/'checkpoints/Instructions/05_QA_and_Package.txt')
(r/'README_QA.md').write_text('''# P-VCNA-003 — QA checkpoint\n\n64 physical shells; 64 structures, 64 editable DOCX, 64 Locator Maps, 64 Metadata records. Content List has 132 entries; 68 directory-only entries were not manufactured. 73 physical footnotes and 112 interpreted rules retained. Approved records: 0.\n\nFresh original-PDF audit: all 86 pages read; 4,124 physical blocks, 985 blank cells and 73 notes show no normalized character-multiset differences. This cannot prove text order, typography, superscripts or clinical semantics. Fresh actual XML audit verifies 5,682 occurrence bookmarks and actual hashes. 300 corporate wrapper/form-footer occurrences are consistently excluded and remain explicitly unlocated. Source figure specification boxes remain textual; no plots generated.\n\nEarlier 77-page same-agent visual inspection evidence and original page previews are retained. Current QA image viewing failed (exec-server transport closed); fresh independent visual and semantic checks are not_run. All quality states remain pending. Eight specifically identified source/fine-structure tasks remain; all 64 also await independent review and human authorization. These are separate counts. See qa/Review_Gaps.json for exact IDs and qa/Study_QA_Report.json for per-template/layer states.\n\nNo new source correction was justified by current static audits. The two genuine prior programming-note role corrections remain in qa/Corrections_Log.json; affected current hashes, bookmarks and metadata parity have been rechecked. Original clinical conflicts are preserved. No optional replacement test was performed.\n\nThis package is an INCOMPLETE CHECKPOINT, not an approved searchable library.\n\n## Specific remaining IDs\n\n'''+''.join('- '+x+'\n' for x in p['remaining_ids']))
print(json.dumps(dict(counts=report['counts'],check_records=len(checks),issues=len(issues),full_study_complete=False)))
